import{_ as r,a as e,b as o,c as s,d as a,e as n,f as i,g as l,h as g,i as h,j as u,k as p}from"./chunks/perspective.DPPPvFKX.js";import{_ as d,o as c,c as m,a2 as f}from"./chunks/framework.Bzj1XTnB.js";const P=JSON.parse('{"title":"Drawing tools and colours","description":"Brushes and making your own, eraser, fill, text, smudge, blur, magic cut, eyedropper, the colour picker and the ruler guides.","frontmatter":{"lang":"en","slug":"drawing-tools","order":3,"title":"Drawing tools and colours","description":"Brushes and making your own, eraser, fill, text, smudge, blur, magic cut, eyedropper, the colour picker and the ruler guides."},"headers":[],"relativePath":"drawing-tools.md","filePath":"drawing-tools.md"}'),y={name:"drawing-tools.md"};function b(w,t,k,S,_,T){return c(),m("div",null,[...t[0]||(t[0]=[f('<h1 id="drawing-tools-and-colours" tabindex="-1">Drawing tools and colours <a class="header-anchor" href="#drawing-tools-and-colours" aria-label="Permalink to &quot;Drawing tools and colours&quot;">​</a></h1><h2 id="brush" tabindex="-1">Brush <a class="header-anchor" href="#brush" aria-label="Permalink to &quot;Brush&quot;">​</a></h2><p>Pick <strong>Brush</strong> in the toolbar, then tap <strong>Brush</strong> on the right pill to choose from <strong>41 brushes</strong> in six groups: Basic (Pen, Pen Soft, Ink, Highlighter, Airbrush, Pixel…), Sketch (Pencil, Crayon, Calligraphy…), Texture (Spray, Grain, Halftone…), Effect (Gradient, 3D Brush, Candy Cane, Sparkles), Shape (Dots, Squares, Dash…) and Fun (Sprinkles, Leaves, Hair, Fur). Brushes you make yourself are at the top, under <strong>My brushes</strong>.</p><p><img src="'+r+'" alt="Brush library"></p><p>Your brush, tool sizes and colours stay as you left them, in every project, even after closing the app.</p><p>Tap a brush to use it, or the <strong>›</strong> next to it to change its settings:</p><p><img src="'+e+'" alt="Brush settings"></p><ul><li><strong>Stabilizer</strong> — smooths out shaky lines. Higher is smoother but follows your finger more slowly.</li><li><strong>Thickness</strong> — 1 to 200 pixels.</li><li><strong>Opacity</strong> — how see-through the stroke is.</li><li><strong>Color</strong> — and for two-colour brushes (Gradient, Candy Cane, Sparkles, Sprinkles, Static) a <strong>Second color</strong>.</li><li><strong>Pressure &amp; advanced</strong> — with a stylus, pressure can change the size and/or opacity.</li></ul><p><strong>Tip:</strong> double-tap the Brush tool to switch the ruler on or off.</p><h3 id="make-your-own-brush" tabindex="-1">Make your own brush <a class="header-anchor" href="#make-your-own-brush" aria-label="Permalink to &quot;Make your own brush&quot;">​</a></h3><p>Tap <strong>New brush</strong> under <strong>My brushes</strong> to open the brush maker. Draw on the paper at the top to try the brush: every change below is painted again on your own line straight away. Tap <strong>✓</strong> to keep the brush; it goes into <strong>My brushes</strong> and into your hand. The <strong>›</strong> next to one of your brushes opens it again to change it.</p><p><img src="'+o+'" alt="Brush maker"></p><ul><li><strong>Name</strong> — what the brush is called in the list.</li><li><strong>Start from</strong> — ready-made looks to begin with: Ink pen, Sketch pencil, Chisel marker, Soft airbrush, Dry brush, Chalk, Splatter, Stars, Twinkles, Hearts, Leaves, Bubbles and Confetti.</li><li><strong>Tip</strong> — the shape the brush stamps along the line: Round, Soft, Pencil, Chalk, Square, Bristle, Splatter, Star, Sparkle, Heart, Leaf, Ring — or <strong>Picture</strong>, any picture from your gallery. A dark shape on light paper or a PNG with a see-through background works best; <strong>Paint with the light parts</strong> flips a light shape on a dark picture. <ul><li><strong>Roundness</strong> squashes the tip into a flat nib, <strong>Angle</strong> turns it, and <strong>Turn with the stroke</strong> makes it follow the direction you draw in (good for leaves, bristles and calligraphy).</li></ul></li><li><strong>Stroke</strong> — <strong>Brush size</strong> and <strong>Color</strong> (the same as in the brush settings), <strong>Spacing</strong> (how far apart the stamps are), <strong>Flow</strong> (how strong each stamp is: below 100% they build up where they overlap) and <strong>Stamps per step</strong>.</li><li><strong>Taper</strong> — how the line thins at its <strong>Start</strong> and <strong>End</strong>, and whether it also fades. The end thins as you lift your finger, once the length of the line is known.</li><li><strong>Randomness</strong> — every stamp a little different: <strong>Size</strong>, <strong>Opacity</strong>, <strong>Angle</strong>, <strong>Scatter</strong> (away from the line), <strong>Hue</strong> and <strong>Brightness</strong>.</li><li><strong>Texture</strong> — paper grain the line is pressed through (Pencil, Crayon, Canvas, Grunge, Dots, Hatch), with its <strong>Depth</strong> and <strong>Scale</strong>. The grain stays on the paper, like a real pencil.</li><li><strong>Save as a copy</strong> and <strong>Delete brush</strong> are at the bottom when you change a brush you made.</li></ul><p>Your brushes are kept with the app, so every project can use them. Size, opacity, colour and smoothing still come from the brush settings, the same as for the built-in brushes.</p><h2 id="eraser" tabindex="-1">Eraser <a class="header-anchor" href="#eraser" aria-label="Permalink to &quot;Eraser&quot;">​</a></h2><p><img src="'+s+'" alt="Eraser with its size outline"></p><p>The eraser removes drawing from the current layer only.</p><ul><li><strong>Size</strong> — 1 to 200 pixels. While you erase, a <strong>circle the size of the eraser</strong> follows your finger, so you can see exactly what will go. (You can turn the circle off in <strong>Settings → Drawing → Eraser outline</strong>.)</li><li><strong>Fade</strong> — softens the eraser&#39;s edge, so drawings fade out at its rim instead of being cut sharply.</li><li><strong>Opacity</strong> — lower opacity erases a little at a time.</li></ul><h2 id="fill" tabindex="-1">Fill <a class="header-anchor" href="#fill" aria-label="Permalink to &quot;Fill&quot;">​</a></h2><p>Tap inside a closed shape to fill it with colour.</p><p><img src="'+a+'" alt="Fill tool"></p><ul><li><strong>Threshold</strong> — how different a colour can be from the spot you tap and still get filled. Raise it if a fill leaves gaps around the edges.</li><li><strong>Sample all layers</strong> (in the fill settings) — the lines on every visible layer act as the edge, but the colour goes on the current layer. Perfect for colouring under a separate line-art layer.</li></ul><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><p>Choose <strong>Text</strong> (in <strong>⋯</strong> if you can&#39;t see it), then tap where the text should go. Its pill on the right sets the <strong>Color</strong>, <strong>Size</strong> and <strong>Font</strong> before you start.</p><p><img src="'+n+'" alt="Text tool"></p><p><img src="'+i+'" alt="Add text"></p><p>Type your words, pick a <strong>Font</strong> (Sans, Serif, Mono, Cursive, Condensed, Poppins), a <strong>Size</strong>, <strong>Bold</strong>/<strong>Italic</strong>, the alignment and a <strong>Color</strong>, then tap <strong>Add</strong>. The text appears as a selection you can move, resize and rotate before you put it down.</p><h2 id="smudge-blur-magic-cut-and-eyedropper" tabindex="-1">Smudge, Blur, Magic cut and Eyedropper <a class="header-anchor" href="#smudge-blur-magic-cut-and-eyedropper" aria-label="Permalink to &quot;Smudge, Blur, Magic cut and Eyedropper&quot;">​</a></h2><p>All four are in the <strong>⋯</strong> card on the toolbar.</p><ul><li><strong>Smudge</strong> — pushes and blends colours like a finger in wet paint. <strong>Strength</strong> sets how far the colour travels.</li><li><strong>Blur</strong> — softens lines under your stroke.</li><li><strong>Magic cut</strong> — tap the background around a drawing and it is lifted off in one go, ready to move, resize or save as an object. Tap inside a drawing instead to cut out just that shape.</li><li><strong>Eyedropper</strong> — tap anywhere to pick that colour. You go straight back to the tool you were using.</li></ul><h2 id="the-colour-picker" tabindex="-1">The colour picker <a class="header-anchor" href="#the-colour-picker" aria-label="Permalink to &quot;The colour picker&quot;">​</a></h2><p>Tap <strong>Color</strong> on the right pill.</p><p><img src="'+l+'" alt="Colour wheel"></p><ul><li><strong>Top bar:</strong> the eyedropper (pick a colour from your drawing), <strong>+</strong> (add this colour to your palette), and the old and new colours — tap the old one to go back to it.</li><li><strong>Tabs at the bottom:</strong><ul><li><strong>Wheel</strong> — hue ring, brightness/saturation in the middle, opacity on the arc. Pinch or double-tap the middle to zoom for fine control.</li><li><strong>Classic</strong> — a square with sliders.</li><li><strong>Harmony</strong> — colours that go together (complementary, triadic and more).</li><li><strong>Value</strong> — type exact HEX, HSV or RGB numbers.</li><li><strong>Swatch</strong> — your recent colours and palettes.</li></ul></li></ul><p><img src="'+g+'" alt="Palettes"></p><p>Toonik comes with palettes (Basic, Sketch, Retro Animation, Neon and more). Tap <strong>New palette</strong> to make your own (up to 12 colours each). <strong>Long-press a colour to replace it</strong>, and swipe a palette to rename, duplicate or delete it.</p><h2 id="ruler-and-guides" tabindex="-1">Ruler and guides <a class="header-anchor" href="#ruler-and-guides" aria-label="Permalink to &quot;Ruler and guides&quot;">​</a></h2><p>Tap <strong>Ruler</strong> on the pill (or double-tap the Brush tool). A bar appears at the bottom.</p><p><img src="'+h+'" alt="Ruler bar"></p><ul><li><strong>Line</strong>, <strong>Circ</strong> (circle/oval) and <strong>Box</strong> — draw along a perfect shape. Move and size the guide with its pink handles. Tap the active shape again to remove it.</li><li><strong>Mirr</strong> — mirror: whatever you draw on one side is drawn on the other too.</li><li><strong>Pers</strong> — perspective guides with 1, 2 or 3 vanishing points (<strong>1PT / 2PT / 3PT</strong>). Strokes that start near a guide line follow it. <strong>Grid</strong> shows more or fewer lines. Drag a pink point to move it. A point that is off the screen or under the bars waits at the edge with a small arrow towards it: drag that one and the point moves with your finger.</li><li><strong>Lock</strong> — keeps the guides from moving by accident.</li><li><strong>✕</strong> — closes the ruler.</li></ul><p><img src="'+u+'" alt="Circle and mirror guides"></p><p><img src="'+p+'" alt="Perspective guides"></p>',42)])])}const B=d(y,[["render",b]]);export{P as __pageData,B as default};
